const UAS = [
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Safari/605.1.15',
  'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:125.0) Gecko/20100101 Firefox/125.0',
  'Mozilla/5.0 (Linux; Android 13; SM-G991B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36'
];
const ua = UAS[Math.floor(Math.random() * UAS.length)];
return [{ json: { userAgent: ua } }];

// ── Kost.com: Regex HTML Parse + Filter + Dedup ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentIds) staticData.sentIds = {};

const now = Date.now();
for (const id in staticData.sentIds) {
  if (now - staticData.sentIds[id] > 86400000) delete staticData.sentIds[id];
}

const html = $input.first().json.data || $input.first().json.body || '';
if (!html || html.length < 500) {
  console.log('Kost.com: empty or blocked');
  return [];
}

const output = [];

// ── Strategy 1: __NEXT_DATA__ or window.__INITIAL_STATE__ ──
const nextDataM = html.match(/<script[^>]+id=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/);
const initStateM = html.match(/window\.__(?:INITIAL_STATE|APP_STATE|PRELOADED_STATE)__\s*=\s*({[\s\S]*?});/);

const embeddedSrc = nextDataM?.[1] || initStateM?.[1];
if (embeddedSrc) {
  try {
    const parsed = JSON.parse(embeddedSrc);
    // Try common paths
    const candidates = [
      parsed?.props?.pageProps?.listings,
      parsed?.props?.pageProps?.data?.listings,
      parsed?.props?.pageProps?.results,
      parsed?.listings,
      parsed?.data?.listings
    ].find(c => Array.isArray(c) && c.length > 0);

    if (candidates) {
      for (const item of candidates) {
        const price = parseInt(String(item.price || item.harga || item.price_per_month || 0).replace(/\D/g, ''));
        if (!price || price < 300000 || price > 800000) continue;

        const locText = [item.address, item.alamat, item.location, item.kota, item.title, item.nama]
          .filter(Boolean).join(' ').toLowerCase();
        if (!locText.includes('surabaya') && !locText.includes('sby')) continue;

        const imgs = (item.photos || item.gambar || item.images || [])
          .map(p => typeof p === 'string' ? p : p?.url || p?.src || '')
          .filter(u => u.startsWith('http')).slice(0, 5);
        if (imgs.length === 0) continue;

        const uid = 'kc_' + (item.id || item.slug || item.kost_id || '');
        if (!uid.replace('kc_', '') || staticData.sentIds[uid]) continue;
        staticData.sentIds[uid] = now;

        const slug = item.slug || item.id;
        output.push({
          json: {
            source: 'kost.com',
            title: item.title || item.nama || 'Kos Surabaya',
            price,
            location: [item.address || item.alamat, item.kota].filter(Boolean).join(', ') || 'Surabaya',
            url: item.url || `https://www.kost.com/kost/${slug}`,
            description: (item.description || item.deskripsi || '').slice(0, 500),
            images: imgs,
            scraped_at: new Date().toISOString()
          }
        });
      }
      if (output.length > 0) {
        console.log(`Kost.com (embedded JSON): ${output.length} listings`);
        return output;
      }
    }
  } catch(e) {
    console.log('Kost.com: embedded JSON parse failed:', e.message);
  }
}

// ── Strategy 2: Regex card extraction ──
// Split by listing article/card boundaries
const cardBoundaries = [
  /<(?:article|div)[^>]+class="[^"]*(?:kost-item|item-kost|listing-card|property-card|kost-card)[^"]*"/g,
  /<(?:article|div)[^>]+id="(?:kost|listing)-\d+"/g
];

let cards = [];
for (const pattern of cardBoundaries) {
  const parts = html.split(pattern);
  if (parts.length > 2) { cards = parts.slice(1); break; }
}

if (cards.length === 0) {
  // Last resort: find all kost.com property URLs
  const urlMatches = [...html.matchAll(/href=["']((?:https?:\/\/(?:www\.)?kost\.com)?\/kost\/[a-z0-9-]+)["']/g)]
    .map(m => m[1].startsWith('http') ? m[1] : 'https://www.kost.com' + m[1])
    .filter((u, i, a) => a.indexOf(u) === i).slice(0, 20);

  const allPrices = [...html.matchAll(/(?:Rp|IDR)[\s.]*([\d]{3}[\d.,]*)/g)]
    .map(m => parseInt(m[1].replace(/[.,]/g, '')))
    .filter(p => p >= 300000 && p <= 800000);

  const allImgs = [...html.matchAll(/https:\/\/(?:cdn|img|photos?|static|s3|cf)[^\s"'<>]*\.(?:jpg|jpeg|webp|png)(?:\?[^"'\s]*)?/g)]
    .map(m => m[0]).filter((u, i, a) => a.indexOf(u) === i);

  for (let i = 0; i < Math.min(urlMatches.length, allPrices.length, 8); i++) {
    const uid = 'kc_' + urlMatches[i].split('/').pop();
    if (staticData.sentIds[uid]) continue;
    staticData.sentIds[uid] = now;

    const imgs = allImgs.slice(i * 3, i * 3 + 5);
    if (imgs.length === 0) continue;

    output.push({
      json: {
        source: 'kost.com',
        title: 'Kos Surabaya',
        price: allPrices[i],
        location: 'Surabaya',
        url: urlMatches[i],
        description: '',
        images: imgs,
        scraped_at: new Date().toISOString()
      }
    });
  }
} else {
  // Parse each card block
  for (let i = 0; i < Math.min(cards.length, 20); i++) {
    const block = cards[i].slice(0, 3000);

    const urlM = block.match(/href=["'](https?:\/\/(?:www\.)?kost\.com\/kost\/[^"'?#]+|\/kost\/[^"'?#]+)["']/);
    const url = urlM ? (urlM[1].startsWith('http') ? urlM[1] : 'https://www.kost.com' + urlM[1]) : null;
    if (!url) continue;

    const priceM = block.match(/(?:Rp|IDR)[\s.]*([\d]{3}[\d.,]*)/);
    if (!priceM) continue;
    const price = parseInt(priceM[1].replace(/[.,]/g, ''));
    if (price < 300000 || price > 800000) continue;

    const imgs = [...block.matchAll(/(?:data-src|data-lazy|src)=["'](https?:\/\/[^"']+\.(?:jpg|jpeg|webp|png)(?:\?[^"']*)?)["']/g)]
      .map(m => m[1]).filter((u, idx, a) => a.indexOf(u) === idx).slice(0, 5);
    if (imgs.length === 0) continue;

    const uid = 'kc_' + url.split('/').pop();
    if (staticData.sentIds[uid]) continue;
    staticData.sentIds[uid] = now;

    const titleM = block.match(/<(?:h[23]|a)[^>]*(?:title|heading)[^>]*>\s*([^<]{5,100})\s*<\/(?:h[23]|a)>/) ||
      block.match(/title=["']([^"']{5,100})["']/);
    const adrM = block.match(/<(?:span|p|div)[^>]*(?:location|address|alamat)[^>]*>\s*([^<]{5,80})\s*<\/(?:span|p|div)>/);

    output.push({
      json: {
        source: 'kost.com',
        title: titleM ? titleM[1].trim() : 'Kos Surabaya',
        price,
        location: adrM ? adrM[1].trim() + ', Surabaya' : 'Surabaya',
        url,
        description: '',
        images: imgs,
        scraped_at: new Date().toISOString()
      }
    });
  }
}

console.log(`Kost.com (regex): ${output.length} listings`);
return output;
